INSERT  IGNORE INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES (32871,0,0,'Translocation complete. Commencing planetary analysis of Azeroth.',15,0,0,0,0,15405,'Algalon the Observer - SAY_ALGALON_INTRO_1');
INSERT  IGNORE INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES (32871,1,0,'Stand back, mortals. I\'m not here to fight you.',15,0,0,0,0,15406,'Algalon the Observer - SAY_ALGALON_INTRO_2');
INSERT  IGNORE INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES (32871,2,0,'It is in the universe\'s best interest to re-originate this planet should my analysis find systemic corruption. Do not interfere.',15,0,0,0,0,15407,'Algalon the Observer - SAY_ALGALON_INTRO_3');
INSERT  IGNORE INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES (32871,3,0,'Your actions are illogical. All possible results for this encounter have been calculated. The Pantheon will receive the Observer\'s message regardless of outcome.',15,0,0,0,0,15386,'Algalon the Observer - SAY_ALGALON_START_TIMER');
INSERT  IGNORE INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES (32871,4,0,'See your world through my eyes: A universe so vast as to be immeasurable - incomprehensible even to your greatest minds.',15,0,0,1,0,15390,'Algalon the Observer - SAY_ALGALON_AGGRO');
INSERT  IGNORE INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES (32871,5,0,'The stars come to my aid!',15,0,0,0,0,15392,'Algalon the Observer - SAY_ALGALON_COLLAPSING_STAR');
INSERT  IGNORE INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES (32871,6,0,'%s begins to Summon Collapsing Stars!',15,0,0,0,0,0,'Algalon the Observer - EMOTE_ALGALON_COLLAPSING_STAR');
INSERT  IGNORE INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES (32871,7,0,'Witness the fury of the cosmos!',15,0,0,0,0,15396,'Algalon the Observer - SAY_ALGALONG_BIG_BANG');
INSERT  IGNORE INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES (32871,8,0,'%s begins to cast Big Bang!',15,0,0,0,0,0,'Algalon the Observer - EMOTE_ALGALON_BIG_BANG');
INSERT  IGNORE INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES (32871,9,0,'You are out of time.',15,0,0,0,0,15394,'Algalon the Observer - SAY_ALGALON_ASCEND');
INSERT  IGNORE INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES (32871,10,0,'%s begins to cast Cosmic Smash!',15,0,0,0,0,0,'Algalon the Observer - EMOTE_ALGALON_COSMIC_SMASH');
INSERT  IGNORE INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES (32871,11,0,'Behold the tools of creation!',15,0,0,0,0,15397,'Algalon the Observer - SAY_ALGALON_PHASE_TWO');
INSERT  IGNORE INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES (32871,12,0,'I have seen worlds bathed in the Makers\' flames, their denizens fading without as much as a whimper. Entire planetary systems born and razed in the time that it takes your mortal hearts to beat once. Yet all throughout, my own heart devoid of emotion... of empathy. I. Have. Felt. Nothing. A million-million lives wasted. Had they all held within them your tenacity? Had they all loved life as you do?',15,0,0,1,0,15393,'Algalon the Observer - SAY_ALGALON_OUTRO_1');
INSERT  IGNORE INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES (32871,13,0,'Perhaps it is your imperfections... that which grants you free will... that allows you to persevere against all cosmically calculated odds. You prevail where the Titan\'s own perfect creations have failed.',15,0,0,1,0,15401,'Algalon the Observer - SAY_ALGALON_OUTRO_2');
INSERT  IGNORE INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES (32871,14,0,'I\'ve rearranged the reply code - your planet will be spared. I cannot be certain of my own calculations anymore.',15,0,0,1,0,15402,'Algalon the Observer - SAY_ALGALON_OUTRO_3');
INSERT  IGNORE INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES (32871,15,0,'I lack the strength to transmit the signal. You must... hurry... find a place of power... close to the skies.',15,0,0,1,0,15403,'Algalon the Observer - SAY_ALGALON_OUTRO_4');
INSERT  IGNORE INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES (32871,16,0,'Do not worry about my fate, Bronzen. If the signal is not transmitted in time, re-origination will proceed regardless. Save... your world...',15,0,0,1,0,15404,'Algalon the Observer - SAY_ALGALON_OUTRO_5');
INSERT  IGNORE INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES (32871,17,0,'Analysis complete. There is partial corruption in the planet\'s life-support systems as well as complete corruption in most of the planet\'s defense mechanisms.',15,0,0,0,0,15398,'Algalon the Observer - SAY_ALGALON_DESPAWN_1');
INSERT  IGNORE INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES (32871,18,0,'Begin uplink: Reply Code: \'Omega\'. Planetary re-origination requested.',15,0,0,0,0,15399,'Algalon the Observer - SAY_ALGALON_DESPAWN_2');
INSERT  IGNORE INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES (32871,19,0,'Farewell, mortals. Your bravery is admirable, for such flawed creatures.',15,0,0,0,0,15400,'Algalon the Observer - SAY_ALGALON_DESPAWN_3');
INSERT  IGNORE INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES (32871,20,0,'Loss of life unavoidable.',15,0,0,0,0,15387,'Algalon the Observer - SAY_ALGALON_KILL');
